// Build comprehensive master report
try {
  const aggregateData = $('Aggregate Results').item.json;
  const aiResponse = $input.item.json;

  // Parse AI response
  let strategy;
  try {
    const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);
    const cleanContent = content.replace(/```(?:json)?\s*([\s\S]*?)```/g, '$1').trim();
    strategy = JSON.parse(cleanContent);
  } catch (parseError) {
    // Fallback strategy
    strategy = {
      master_clusters: [
        {
          pillar_name: 'Primary Topic Cluster',
          primary_keywords: aggregateData.allKeywords.slice(0, 5),
          supporting_keywords: aggregateData.allRelatedKeywords.slice(0, 10).map(k => k.keyword),
          recommended_strategy: 'Create comprehensive content covering all primary keywords',
          content_types: ['pillar page', 'blog series'],
          estimated_difficulty: 'medium',
          strategic_priority: 5
        }
      ],
      content_strategy: {
        quick_wins: aggregateData.topOpportunities.slice(0, 3).map(o => o.keyword),
        long_term_targets: aggregateData.allKeywords.slice(0, 5),
        avoid: []
      },
      market_insights: {
        dominant_themes: ['General'],
        content_gaps: ['Various opportunities identified'],
        competition_level: 'medium'
      }
    };
  }

  // Build master report
  const masterReport = {
    summary: {
      total_keywords_analyzed: aggregateData.totalKeywords,
      successful_analyses: aggregateData.successfulKeywords,
      failed_analyses: aggregateData.failedKeywords,
      total_related_keywords: aggregateData.aggregateMetrics.totalRelatedKeywords,
      total_serp_results: aggregateData.aggregateMetrics.totalSerpResults,
      analysis_timestamp: aggregateData.config.timestamp,
      workflow_version: '2.0-bulk'
    },
    aggregate_scores: {
      avg_difficulty: aggregateData.aggregateMetrics.avgDifficulty,
      avg_opportunity: aggregateData.aggregateMetrics.avgOpportunity,
      priority_distribution: aggregateData.aggregateMetrics.priorityDistribution
    },
    top_opportunities: aggregateData.topOpportunities,
    strategic_clusters: strategy.master_clusters || [],
    content_strategy: strategy.content_strategy || {},
    market_insights: strategy.market_insights || {},
    individual_keyword_results: aggregateData.individualResults.map(r => ({
      keyword: r.keyword,
      difficulty_score: r.difficultyScore,
      opportunity_score: r.opportunityScore,
      priority: r.priority,
      combined_score: r.combinedScore,
      serp_features: r.serpFeatures,
      total_serp_results: (r.serpOverview || []).length,
      related_keywords_count: (r.relatedKeywords || []).length,
      content_gaps_summary: {
        missing_topics: (r.contentGaps?.missingSubtopics || []).length,
        thin_areas: (r.contentGaps?.thinContentAreas || []).length
      }
    })),
    failed_keywords: aggregateData.failedList,
    metadata: {
      search_config: {
        depth: aggregateData.config.depth,
        location: aggregateData.config.location,
        language: aggregateData.config.language,
        batch_size: aggregateData.config.batchSize,
        batch_delay_ms: aggregateData.config.batchDelay
      },
      processing_stats: {
        total_api_calls: aggregateData.successfulKeywords,
        estimated_cost_usd: parseFloat((aggregateData.successfulKeywords * 0.009).toFixed(2)),
        keywords_per_minute: parseFloat((aggregateData.successfulKeywords / ((aggregateData.successfulKeywords * aggregateData.config.batchDelay) / 60000)).toFixed(2))
      }
    }
  };

  return masterReport;

} catch (error) {
  throw new Error(`Master report building failed: ${error.message}`);
}
